package org.aegis.android;

import android.content.*;
import android.os.*;
import java.util.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;

final class CoreBrokerClient implements AutoCloseable {
    private final Context context;private final PrivateVault vault;private final Runnable locked,exited;private volatile IBinder broker;private volatile boolean bound,closed;private final BrokerLease leaseState=new BrokerLease();
    CoreBrokerClient(Context c,Runnable locked,Runnable exited){context=c;vault=new PrivateVault(c);this.locked=locked;this.exited=exited;}
    private final Binder observer=new Binder(){@Override protected boolean onTransact(int code,Parcel data,Parcel reply,int flags){if(code!=1)return false;String pkg=PackageTrust.caller(context);if(!AndroidPolicy.CORE.equals(pkg))throw new SecurityException("Недоверенный отзыв");data.enforceInterface(CoreBrokerService.DESCRIPTOR);int fullExit=data.readInt();data.enforceNoDataAvail();if(fullExit<0||fullExit>1)throw new SecurityException("Некорректное событие сессии");invalidate();if(fullExit==1)exited.run();return true;}};
    private void coreDied(){invalidate();exited.run();}
    private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder service){if(closed)return;try{PackageTrust.verifyInstalled(context,AndroidPolicy.CORE);broker=service;service.linkToDeath(CoreBrokerClient.this::coreDied,0);observe();refresh();}catch(Exception denied){invalidate();}}public void onServiceDisconnected(ComponentName name){coreDied();}public void onBindingDied(ComponentName name){coreDied();}public void onNullBinding(ComponentName name){coreDied();}};
    void connect(){if(closed)return;try{PackageTrust.verifyInstalled(context,AndroidPolicy.CORE);Intent i=new Intent();i.setComponent(new ComponentName(AndroidPolicy.CORE,CoreBrokerService.class.getName()));bound=context.bindService(i,connection,Context.BIND_AUTO_CREATE);}catch(Exception unavailable){invalidate();}}
    boolean active(){long now=SystemClock.elapsedRealtime();if(leaseState.active(now))return true;if(leaseState.expire(now))locked.run();return false;}
    IdentityProtocol.Capability capability(){return leaseState.capability(SystemClock.elapsedRealtime());}
    private synchronized Parcel request(int code,boolean proof)throws Exception {
        IBinder b=broker;if(closed||b==null)throw new SecurityException("Главное приложение недоступно");Parcel data=Parcel.obtain(),reply=Parcel.obtain();data.writeInterfaceToken(CoreBrokerService.DESCRIPTOR);
        try{if(proof){Parcel answer=request(CoreBrokerService.CHALLENGE,false);String nonce;try{nonce=answer.readString();}finally{answer.recycle();}byte[] key=vault.appPublicKey();data.writeByteArray(key);data.writeByteArray(vault.prove(AndroidPolicy.proof(context.getPackageName(),nonce,key,code)));}if(!b.transact(code,data,reply,0))throw new SecurityException("Версия IPC не поддерживается");reply.readException();return reply;}catch(Exception failure){reply.recycle();throw failure;}finally{data.recycle();}}
    synchronized void refresh()throws Exception {
        long expectedEpoch=leaseState.epoch();Parcel answer=request(CoreBrokerService.LEASE,true);try{String pin=answer.readString(),wire=answer.readString();long deadline=answer.readLong();answer.enforceNoDataAvail();byte[] server=IdentityProtocol.unb64(pin,44),saved=vault.get("authority-pin");if(saved!=null&&!java.security.MessageDigest.isEqual(saved,server))throw new SecurityException("Ключ Identity изменён");IdentityProtocol.Capability c=IdentityProtocol.decodeCapability(wire);AndroidPolicy.validateCapability(c,server,context.getPackageName(),vault.appPublicKey(),System.currentTimeMillis());if(deadline<=SystemClock.elapsedRealtime()||deadline-SystemClock.elapsedRealtime()>AndroidPolicy.LOCAL_LEASE)throw new SecurityException("Срок IPC допуска");vault.put("authority-pin",server);leaseState.install(expectedEpoch,c,Math.min(deadline,SystemClock.elapsedRealtime()+Math.max(0,c.offlineUntil-System.currentTimeMillis())),SystemClock.elapsedRealtime());}finally{answer.recycle();}
    }
    synchronized void touched(){if(!active())return;try{Parcel reply=request(CoreBrokerService.TOUCH,true);reply.recycle();}catch(Exception denied){invalidate();}}
    synchronized com.google.gson.JsonObject publicConfig()throws Exception {
        Parcel reply=request(CoreBrokerService.PUBLIC_CONFIG,false);try{com.google.gson.JsonObject j=org.securemail.client.community.CommunityJson.parse(reply.readString().getBytes(java.nio.charset.StandardCharsets.UTF_8));byte[] pin=IdentityProtocol.unb64(j.get("serverKey").getAsString(),44);IdentityProtocol.publicKey(pin);byte[] old=vault.get("authority-pin");if(old!=null&&!java.security.MessageDigest.isEqual(old,pin))throw new SecurityException("Ключ сервера изменён");org.securemail.protocol.Limits.onion(j.get("onion").getAsString());int socks=j.get("socksPort").getAsInt();if(socks<1||socks>65535)throw new SecurityException("Порт SOCKS");return j;}finally{reply.recycle();}
    }
    synchronized void requestGrant()throws Exception {
        Parcel cfg=request(CoreBrokerService.PUBLIC_CONFIG,false);byte[] server;try{com.google.gson.JsonObject json=org.securemail.client.community.CommunityJson.parse(cfg.readString().getBytes(java.nio.charset.StandardCharsets.UTF_8));server=IdentityProtocol.unb64(json.get("serverKey").getAsString(),44);IdentityProtocol.publicKey(server);}finally{cfg.recycle();}byte[] old=vault.get("authority-pin");if(old!=null&&!java.security.MessageDigest.isEqual(old,server))throw new SecurityException("Серверный ключ изменён");
        Parcel proposed=request(CoreBrokerService.PROPOSE,true);String wire;try{wire=proposed.readString();}finally{proposed.recycle();}byte[] key=vault.appPublicKey();AppGrantProposal proposal=new AppGrantProposal(context.getPackageName(),key,wire,server,System.currentTimeMillis());byte[] consent=vault.prove(proposal.bytes);
        Parcel challenge=request(CoreBrokerService.CHALLENGE,false);String nonce;try{nonce=challenge.readString();}finally{challenge.recycle();}Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken(CoreBrokerService.DESCRIPTOR);data.writeByteArray(key);data.writeByteArray(vault.prove(AndroidPolicy.proof(context.getPackageName(),nonce,key,CoreBrokerService.CONSENT)));data.writeString(proposal.nonce);data.writeByteArray(consent);if(!broker.transact(CoreBrokerService.CONSENT,data,reply,0))throw new SecurityException("Версия IPC не поддерживается");reply.readException();String issued=reply.readString();IdentityProtocol.Capability cap=IdentityProtocol.decodeCapability(issued);AndroidPolicy.validateCapability(cap,server,context.getPackageName(),key,System.currentTimeMillis());}finally{data.recycle();reply.recycle();Arrays.fill(consent,(byte)0);}refresh();
    }
    synchronized void countChanged(int count)throws Exception {
        IBinder b=broker;if(b==null||!active())throw new SecurityException("Сессия заблокирована");Parcel challenge=request(CoreBrokerService.CHALLENGE,false);String nonce;try{nonce=challenge.readString();}finally{challenge.recycle();}byte[] key=vault.appPublicKey();Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken(CoreBrokerService.DESCRIPTOR);data.writeByteArray(key);data.writeByteArray(vault.prove(AndroidPolicy.proof(context.getPackageName(),nonce,key,CoreBrokerService.EVENT)));data.writeString(java.util.UUID.randomUUID().toString().replace("-",""));data.writeInt(count);b.transact(CoreBrokerService.EVENT,data,reply,0);reply.readException();}finally{data.recycle();reply.recycle();}
    }
    synchronized String stageVoice()throws Exception {capability();Parcel reply=request(CoreBrokerService.VOICE_STAGE,true);try{return reply.readString();}finally{reply.recycle();}}
    synchronized String pendingVoice()throws Exception {capability();Parcel reply=request(CoreBrokerService.VOICE_PENDING,true);try{return reply.readString();}finally{reply.recycle();}}
    synchronized byte[] receiveVoice()throws Exception {capability();Parcel reply=request(CoreBrokerService.VOICE_RECEIVE,true);try{byte[] value=reply.createByteArray();if(value==null||value.length>65536)throw new SecurityException("Размер допуска Гласа");return value;}finally{reply.recycle();}}
    synchronized void deliverVoice(String id,byte[] grant)throws Exception {
        capability();IdentityProtocol.nonceValue(id);if(grant==null||grant.length>65536)throw new SecurityException("Размер допуска Гласа");Parcel challenge=request(CoreBrokerService.CHALLENGE,false);String nonce;try{nonce=challenge.readString();}finally{challenge.recycle();}byte[] key=vault.appPublicKey();Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken(CoreBrokerService.DESCRIPTOR);data.writeByteArray(key);data.writeByteArray(vault.prove(AndroidPolicy.proof(context.getPackageName(),nonce,key,CoreBrokerService.VOICE_DELIVER)));data.writeString(id);data.writeByteArray(grant);if(!broker.transact(CoreBrokerService.VOICE_DELIVER,data,reply,0))throw new SecurityException("Версия IPC");reply.readException();}finally{data.recycle();reply.recycle();}
    }
    synchronized String publishVoice(int port)throws Exception {
        capability();if(port<1||port>65535)throw new SecurityException("Порт Гласа");Parcel challenge=request(CoreBrokerService.CHALLENGE,false);String nonce;try{nonce=challenge.readString();}finally{challenge.recycle();}byte[] key=vault.appPublicKey();Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken(CoreBrokerService.DESCRIPTOR);data.writeByteArray(key);data.writeByteArray(vault.prove(AndroidPolicy.proof(context.getPackageName(),nonce,key,CoreBrokerService.VOICE_PUBLISH)));data.writeInt(port);if(!broker.transact(CoreBrokerService.VOICE_PUBLISH,data,reply,0))throw new SecurityException("Версия IPC");reply.readException();String onion=reply.readString();org.securemail.protocol.Limits.onion(onion);return onion;}finally{data.recycle();reply.recycle();}
    }
    synchronized void dropVoice()throws Exception {if(!active())return;Parcel reply=request(CoreBrokerService.VOICE_DROP,true);reply.recycle();}
    private void observe()throws Exception {
        IBinder b=broker;if(closed||b==null)return;Parcel challenge=request(CoreBrokerService.CHALLENGE,false);String nonce;try{nonce=challenge.readString();}finally{challenge.recycle();}byte[] key=vault.appPublicKey();Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken(CoreBrokerService.DESCRIPTOR);data.writeByteArray(key);data.writeByteArray(vault.prove(AndroidPolicy.proof(context.getPackageName(),nonce,key,CoreBrokerService.OBSERVE)));data.writeStrongBinder(observer);b.transact(CoreBrokerService.OBSERVE,data,reply,0);reply.readException();}finally{data.recycle();reply.recycle();}}
    private void invalidate(){if(leaseState.clear())locked.run();}
    @Override public void close(){closed=true;invalidate();broker=null;if(bound){context.unbindService(connection);bound=false;}}
}
